solution:
function flattenArray(arr, depth) {
  const d = depth === undefined ? 1 : depth;
  if (d <= 0) return arr.slice();
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (Array.isArray(item)) {
      result.push(...flattenArray(item, d - 1));
    } else {
      result.push(item);
    }
  }
  return result;
}

